    "tr": "Bunlar mevcut sezonun istatistikleridir. Kalıcı unvanlar ve rozetler sıfırlanmaz.",
    "ur": "یہ موجودہ سیزن کے اعداد و شمار ہیں۔ مستقل القاب اور اعزاز ختم نہیں ہوتے۔",
