  "settings.eaf85ae743": {
    "ar": "زاد الإسلام مساحة للقرآن والذكر والمطالعة، تجمع الورد اليومي والأحاديث والكتب ودروس السيرة والمقاطع النافعة.",
    "en": "Zad El-Islam brings together daily Quran reading, remembrance, Hadith, books, Seerah lessons, and beneficial videos.",
    "fr": "Zad El-Islam réunit lecture du Coran, invocations, hadiths, livres, cours de biographie prophétique et vidéos utiles.",
    "id": "Zad El-Islam menggabungkan bacaan Al-Quran harian, zikir, hadis, buku, pelajaran sirah, dan video bermanfaat.",
    "tr": "Zad El-Islam günlük Kur’an, zikir, hadis, kitaplar, siyer dersleri ve faydalı videoları bir araya getirir.",
    "ur": "Zad El-Islam میں روزانہ قرآن، ذکر، احادیث، کتابیں، سیرت کے اسباق اور مفید ویڈیوز یکجا ہیں۔",
    "es": "Zad El-Islam reúne lectura diaria del Corán, recuerdo, hadices, libros, lecciones de biografía profética y vídeos útiles."
  },
  "settings.36be01299d": {
    "ar": "نقاط المتابعة للتشجيع على الاستمرار، وليست مقياسًا للحسنات. النصوص الدينية من المحتوى والمصادر الأصلية للموقع.",
    "en": "Progress points encourage consistency, not religious merit. Religious texts retain the site’s original content and sources.",
    "fr": "Les points encouragent la régularité et ne mesurent pas les mérites spirituels. Les textes religieux conservent leurs contenus et sources d’origine.",
    "id": "Poin mendorong konsistensi, bukan mengukur pahala. Teks agama tetap mengikuti konten dan sumber asli situs.",
    "tr": "Puanlar devamlılığı teşvik eder, sevap ölçmez. Dinî metinler özgün içerik ve kaynaklarıyla korunur.",
    "ur": "پوائنٹس پابندی کی حوصلہ افزائی ہیں، نیکیوں کا پیمانہ نہیں۔ دینی متون اپنے اصل مواد اور ماخذ کے مطابق ہیں۔",
    "es": "Los puntos animan a la constancia y no miden el mérito religioso. Los textos conservan el contenido y las fuentes originales."
  },
