  "index.c591128844": {
    "ar": "يتم جلب النص القرآني بالرسم العثماني من مصدر إلكتروني، ولا تُكتب الآيات يدويًا داخل البرنامج.",
    "en": "Uthmani Quran text is retrieved from an online source; verses are not manually written into the app.",
    "fr": "Le texte coranique uthmani provient d’une source en ligne ; les versets ne sont pas saisis manuellement dans l’application.",
    "id": "Teks Al-Quran rasm Utsmani diambil dari sumber daring; ayat tidak ditulis manual di aplikasi.",
    "tr": "Osmanî hatlı Kur’an metni çevrim içi kaynaktan alınır; ayetler uygulamaya elle yazılmaz.",
    "ur": "رسمِ عثمانی کا قرآنی متن آن لائن ماخذ سے آتا ہے؛ آیات ایپ میں ہاتھ سے نہیں لکھی جاتیں۔",
    "es": "El texto coránico uthmani procede de una fuente en línea; las aleyas no se escriben manualmente en la aplicación."
  },
