    "id": "Simpan tanggal mulai dan jumlah harian. Hapus tanda selesai atau muat ulang teks bila perlu.",
    "tr": "Başlangıç tarihini ve günlük miktarı kaydedin. Gerekirse işaretleri silin veya metni yeniden yükleyin.",
    "ur": "ابتدائی تاریخ اور روزانہ مقدار محفوظ کریں۔ ضرورت پر تکمیل کے نشان مٹا یا متن دوبارہ لوڈ کر سکتے ہیں۔",
