  "index.df273e051f": {
    "ar": "اختر قسمًا لتصفح الرسائل والبحث فيها وحفظ المفضلة ونسخ الرسائل. تبقى علامات الكتب محفوظة؛ ملفات الكتب الأصلية غير مرفقة.",
    "en": "Choose a section to browse messages, search, save favorites, or copy a message. Book bookmarks remain saved; the original book files are not included.",
    "fr": "Choisissez une rubrique pour lire, rechercher, enregistrer ou copier les messages. Les repères de livres sont conservés ; les fichiers originaux ne sont pas inclus.",
    "id": "Pilih bagian untuk membaca, mencari, menyimpan favorit, atau menyalin pesan. Penanda buku tetap tersimpan; berkas asli tidak disertakan.",
    "tr": "Mesajları okumak, aramak, kaydetmek veya kopyalamak için bölüm seçin. Kitap işaretleri korunur; özgün dosyalar eklenmedi.",
    "ur": "پیغامات دیکھنے، تلاش، پسندیدہ محفوظ کرنے یا نقل کے لیے حصہ چنیں۔ کتابوں کے نشان محفوظ ہیں؛ اصل فائلیں شامل نہیں۔",
    "es": "Elige una sección para leer, buscar, guardar favoritos o copiar mensajes. Los marcadores se conservan; los archivos originales no están incluidos."
  },
