    "id": "Pencarian dibuka di situs resmi Dorar demi keamanan data dan penilaian terbaru dari sumber.",
    "tr": "Veri güvenliği ve güncel hadis hükümleri için arama resmî Dorar sitesinde açılır.",
    "ur": "معلومات کی حفاظت اور تازہ احکام کے لیے تلاش درر سنیہ کی سرکاری سائٹ پر کھلتی ہے۔",
