  "index.21a6a2d756": {
    "ar": "النقاط للمستويات والأوسمة والتحفيز فقط؛ جميع أقسام العلم والذكر تبقى مفتوحة للجميع، وهي ليست مقياسًا للأجر أو الحسنات.",
    "en": "Points support levels, badges, and motivation. Learning and remembrance stay open to all. Points do not measure religious reward.",
    "fr": "Les points servent aux niveaux, badges et encouragements. Savoir et invocations restent ouverts à tous. Ils ne mesurent pas la récompense spirituelle.",
    "id": "Poin untuk level, lencana, dan motivasi. Ilmu dan zikir tetap terbuka bagi semua. Poin tidak mengukur pahala.",
    "tr": "Puanlar seviye, rozet ve teşvik içindir. İlim ve zikir herkese açıktır. Puanlar sevabı ölçmez.",
    "ur": "پوائنٹس درجوں، اعزاز اور حوصلے کے لیے ہیں۔ علم اور ذکر سب کے لیے کھلے ہیں۔ یہ اجر کا پیمانہ نہیں۔",
    "es": "Los puntos sirven para niveles, insignias y motivación. Aprendizaje y recuerdo siguen abiertos a todos. No miden la recompensa religiosa."
  },
